import { LOW_STOCK_THRESHOLD } from '@shop/shared';

export type StockLevel = 'in-stock' | 'low-stock' | 'out-of-stock';

export function stockLevelFor(available: number): StockLevel {
  if (available <= 0) return 'out-of-stock';
  return available <= LOW_STOCK_THRESHOLD ? 'low-stock' : 'in-stock';
}

const LABELS: Record<StockLevel, (available: number) => string> = {
  'in-stock': () => 'In stock',
  'low-stock': (available) => `Only ${available} left`,
  'out-of-stock': () => 'Sold out',
};

export function StockBadge({ available }: { available: number }) {
  const level = stockLevelFor(available);
  const color = level === 'in-stock' ? 'green' : level === 'low-stock' ? 'amber' : 'red';
  return (
    <span
      className={`rounded-[6px] px-2 py-0.5 text-[13px] bg-${color}-100 ${
        level === 'out-of-stock'
          ? 'text-[#b91c1c]'
          : level === 'low-stock'
            ? 'text-[#b45309]'
            : 'text-[#15803d]'
      }`}
    >
      {LABELS[level](available)}
    </span>
  );
}

